        .iter()
        .filter_map(|p| match p {
            ContentPart::Text { text } if is_blank(text) => None,
            ContentPart::Text { text } => Some(json!({"type": "text", "text": text})),
            ContentPart::ToolUse { call_id, name, args } => Some(json!({
